-- Per-language names for menu items (English stays the main name: it goes on bills and reports),
-- and Mausam's printed menu loaded into the POS.

ALTER TABLE menu_items ADD COLUMN name_hi TEXT;
ALTER TABLE menu_items ADD COLUMN name_kn TEXT;

-- Mausam's menu, from the printed card (prices in paise). Safe on a database that already has a menu:
-- a category is only added when none has the same name, and an item only when that category has no
-- item of the same name (an existing item just gets its Hindi and Kannada names filled in if blank).

INSERT INTO menu_categories (name, name_hi, name_kn, sort) SELECT 'Pav Bhaji', 'पाव भाजी', 'ಪಾವ್ ಭಾಜಿ', 10 WHERE NOT EXISTS (SELECT 1 FROM menu_categories WHERE lower(name) = lower('Pav Bhaji'));
INSERT INTO menu_categories (name, name_hi, name_kn, sort) SELECT 'Dosa', 'डोसा', 'ದೋಸೆ', 20 WHERE NOT EXISTS (SELECT 1 FROM menu_categories WHERE lower(name) = lower('Dosa'));
INSERT INTO menu_categories (name, name_hi, name_kn, sort) SELECT 'Chinese', 'चाइनीज़', 'ಚೈನೀಸ್', 30 WHERE NOT EXISTS (SELECT 1 FROM menu_categories WHERE lower(name) = lower('Chinese'));
INSERT INTO menu_categories (name, name_hi, name_kn, sort) SELECT 'Drinks', 'ड्रिंक्स', 'ಡ್ರಿಂಕ್ಸ್', 40 WHERE NOT EXISTS (SELECT 1 FROM menu_categories WHERE lower(name) = lower('Drinks'));
UPDATE menu_categories SET name_hi = CASE lower(name) WHEN lower('Pav Bhaji') THEN 'पाव भाजी' WHEN lower('Dosa') THEN 'डोसा' WHEN lower('Chinese') THEN 'चाइनीज़' WHEN lower('Drinks') THEN 'ड्रिंक्स' ELSE name_hi END,
  name_kn = CASE lower(name) WHEN lower('Pav Bhaji') THEN 'ಪಾವ್ ಭಾಜಿ' WHEN lower('Dosa') THEN 'ದೋಸೆ' WHEN lower('Chinese') THEN 'ಚೈನೀಸ್' WHEN lower('Drinks') THEN 'ಡ್ರಿಂಕ್ಸ್' ELSE name_kn END
  WHERE name_hi IS NULL AND name_kn IS NULL AND lower(name) IN (lower('Pav Bhaji'), lower('Dosa'), lower('Chinese'), lower('Drinks'));

-- Pav Bhaji
INSERT INTO menu_items (category_id, name, name_hi, name_kn, price, veg, sort) SELECT (SELECT id FROM menu_categories WHERE lower(name) = lower('Pav Bhaji') ORDER BY active DESC, id LIMIT 1), 'Pav Bhaji', 'पाव भाजी', 'ಪಾವ್ ಭಾಜಿ', 22000, 1, 10 WHERE NOT EXISTS (SELECT 1 FROM menu_items WHERE category_id = (SELECT id FROM menu_categories WHERE lower(name) = lower('Pav Bhaji') ORDER BY active DESC, id LIMIT 1) AND lower(name) = lower('Pav Bhaji'));
